import React, { useState, useEffect, useRef } from "react";

const W = 780, H = 480;
const POWER_TYPES = ["SPEED", "MISSILE", "DOUBLE", "LASER", "OPTION", "SHIELD"];
const POWER_COLORS = { SPEED: "#0ff", MISSILE: "#f80", DOUBLE: "#ff0", LASER: "#f0f", OPTION: "#0f0", SHIELD: "#88f" };
let eid = 0;

const BOSS1_SRC = "data:image/jpeg;base64,";
const BOSS2_SRC = "data:image/jpeg;base64,";
const BOSS3_SRC = "data:image/jpeg;base64,";
const BOSS4_SRC = "data:image/jpeg;base64,";
const BGM_SRC = "data:audio/mpeg;base64,";

function mkEnemy(x, y, type) {
  return { id: eid++, x, y, type, hp: type === "boss" ? 40 : type === "mid" ? 3 : 1, vx: type === "boss" ? -1 : -2.5, phase: Math.random() * Math.PI * 2, shootTimer: Math.random() * 2 };
}

function initState() {
  return {
    player: { x: 100, y: H / 2, invincible: 0, speed: 1, optionCount: 0, options: [] },
    bullets: [], enemyBullets: [], enemies: [], particles: [], capsules: [],
    powerBar: [], score: 0,
    stars: Array.from({ length: 110 }, () => ({ x: Math.random() * W, y: Math.random() * H, s: Math.random() * 2 + 0.5, v: Math.random() * 1.5 + 0.5 })),
    spawnTimer: 0, shootTimer: 0, missileCooldown: 0,
    hasMissile: false, hasDouble: false, hasLaser: false, hasShield: false,
    wave: 0, lives: 3, bossSpawned: false, bossTimer: 8, bossCount: 0,
    finalBossKilled: false, finalBossDefeated: false, clearTimer: 0,
  };
}

function GameClear({ score, onRetry, onTitle }) {
  const [stars] = React.useState(() => Array.from({length: 80}, () => ({
    x: Math.random() * 100, y: Math.random() * 100,
    s: Math.random() * 3 + 1, t: Math.random() * Math.PI * 2
  })));
  const [tick, setTick] = React.useState(0);
  React.useEffect(() => {
    const id = setInterval(() => setTick(t => t + 1), 50);
    return () => clearInterval(id);
  }, []);
  const scale = Math.min(1 + tick * 0.02, 3); // Gradually scale up to 3x
  return (
    <div style={{ background:"#000010", width:"100%", minHeight:550, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", fontFamily:"monospace", color:"#fff", position:"relative", overflow:"hidden" }}>
      {stars.map((st, i) => (
        <div key={i} style={{ position:"absolute", left:`${st.x}%`, top:`${st.y}%`, width:st.s, height:st.s, borderRadius:"50%", background:`hsl(${(tick*3+i*20)%360},100%,80%)`, opacity: 0.6 + 0.4*Math.sin(tick*0.1+st.t) }} />
      ))}
      <div style={{ fontSize:48, fontWeight:"bold", letterSpacing:6, background:"linear-gradient(90deg,#f0f,#0cf,#ff0,#0f0,#f0f)", WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent", backgroundSize:"200%", backgroundPosition:`${tick*2}% 0`, textShadow:"none", filter:"drop-shadow(0 0 10px #f0f)", marginBottom: 20 }}>
        GAME CLEAR
      </div>
      <div style={{ fontSize:22, marginTop:20, color:"#ff0" }}>SCORE: {score.toString().padStart(7,"0")}</div>
      <div style={{ marginTop:30, fontSize:24, color:"#f00", lineHeight:2.2, textAlign:"center", maxWidth:400, fontWeight:"bold" }}>
        次は鬼地獄モードだ！
      </div>
      <div style={{ display:"flex", gap:16, marginTop:36 }}>
        <button onClick={onRetry} style={{ padding:"16px 44px", fontSize:16, fontWeight:"bold", background:"linear-gradient(135deg,#0080ff,#00c0ff)", border:"none", borderRadius:8, color:"#fff", cursor:"pointer", letterSpacing:2, minWidth:"140px", minHeight:"52px" }}>もう一度</button>
        <button onClick={onTitle} style={{ padding:"16px 44px", fontSize:16, background:"transparent", border:"2px solid #88f", borderRadius:8, color:"#aaf", cursor:"pointer", minWidth:"140px", minHeight:"52px" }}>タイトルへ</button>
      </div>
      {/* Boss 3 image scaling up */}
      <div style={{ position:"absolute", top:"50%", left:"50%", transform:`translate(-50%, -50%) scale(${scale})`, opacity: tick > 10 ? 1 : 0, transition:"opacity 1s" }}>
        <img src={BOSS3_SRC} alt="Boss 3" style={{ width:"110px", height:"110px" }} />
      </div>
    </div>
  );
}

export default function App() {
  const [screen, setScreen] = useState("title");
  const [endTimer, setEndTimer] = useState(0);
  const [finalScore, setFinalScore] = useState(0);
  const stateRef = useRef(null);
  const keysRef = useRef({});
  const canvasRef = useRef(null);
  const animRef = useRef(null);
  const lastRef = useRef(null);
  const audioRef = useRef(null);
  const bossImgsRef = useRef([null, null, null]);

  useEffect(() => {
    // Preload boss images
    const srcs = [BOSS1_SRC, BOSS2_SRC, BOSS3_SRC];
    srcs.forEach((src, i) => {
      const img = new Image();
      img.src = src;
      bossImgsRef.current[i] = img;
    });
    const img4 = new Image(); img4.src = BOSS4_SRC; bossImgsRef.current[3] = img4;
    // Setup BGM
    const audio = new Audio(BGM_SRC);
    audio.loop = true;
    audio.volume = 0.5;
    audioRef.current = audio;
    return () => { audio.pause(); };
  }, []);

  const startGame = () => {
    stateRef.current = initState();
    setScreen("game");
    audioRef.current?.play().catch(()=>{});
  };

  useEffect(() => {
    const down = (e) => {
      keysRef.current[e.key] = true;
      if ([" ", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(e.key)) e.preventDefault();
    };
    const up = (e) => { keysRef.current[e.key] = false; };
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);

    // Touch events for swipe control
    let touchStartX = 0;
    let touchStartY = 0;
    let isSwiping = false;

    const handleTouchStart = (e) => {
      if (e.touches.length === 1) {
        touchStartX = e.touches[0].clientX;
        touchStartY = e.touches[0].clientY;
        isSwiping = true;
      }
    };

    const handleTouchMove = (e) => {
      if (!isSwiping || e.touches.length !== 1) return;
      e.preventDefault(); // Prevent scrolling
      const touchX = e.touches[0].clientX;
      const touchY = e.touches[0].clientY;
      const deltaX = touchX - touchStartX;
      const deltaY = touchY - touchStartY;

      // Clear previous directions
      keysRef.current["ArrowUp"] = false;
      keysRef.current["ArrowDown"] = false;
      keysRef.current["ArrowLeft"] = false;
      keysRef.current["ArrowRight"] = false;

      // Determine direction based on swipe
      const threshold = 30; // Minimum distance to consider as swipe
      if (Math.abs(deltaX) > Math.abs(deltaY)) {
        if (Math.abs(deltaX) > threshold) {
          keysRef.current[deltaX > 0 ? "ArrowRight" : "ArrowLeft"] = true;
        }
      } else {
        if (Math.abs(deltaY) > threshold) {
          keysRef.current[deltaY > 0 ? "ArrowDown" : "ArrowUp"] = true;
        }
      }
    };

    const handleTouchEnd = (e) => {
      isSwiping = false;
      keysRef.current["ArrowUp"] = false;
      keysRef.current["ArrowDown"] = false;
      keysRef.current["ArrowLeft"] = false;
      keysRef.current["ArrowRight"] = false;
    };

    window.addEventListener("touchstart", handleTouchStart, { passive: false });
    window.addEventListener("touchmove", handleTouchMove, { passive: false });
    window.addEventListener("touchend", handleTouchEnd);

    return () => { 
      window.removeEventListener("keydown", down); 
      window.removeEventListener("keyup", up);
      window.removeEventListener("touchstart", handleTouchStart);
      window.removeEventListener("touchmove", handleTouchMove);
      window.removeEventListener("touchend", handleTouchEnd);
    };
  }, []);

  useEffect(() => {
    if (screen !== "game") return;
    lastRef.current = performance.now();
    const loop = (now) => {
      const dt = Math.min((now - (lastRef.current || now)) / 1000, 0.05);
      lastRef.current = now;
      if (stateRef.current) tick(dt);
      animRef.current = requestAnimationFrame(loop);
    };
    animRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animRef.current);
  }, [screen]);

  function tick(dt) {
    const s = stateRef.current;
    const keys = keysRef.current;
    const ctx = canvasRef.current?.getContext("2d");
    if (!ctx) return;

    for (const st of s.stars) { st.x -= st.v * 55 * dt; if (st.x < 0) { st.x = W; st.y = Math.random() * H; } }

    const sp = (2 + s.player.speed * 0.8) * 165;
    if (keys["ArrowUp"] || keys["w"]) s.player.y -= sp * dt;
    if (keys["ArrowDown"] || keys["s"]) s.player.y += sp * dt;
    if (keys["ArrowLeft"] || keys["a"]) s.player.x -= sp * dt;
    if (keys["ArrowRight"] || keys["d"]) s.player.x += sp * dt;
    s.player.x = Math.max(20, Math.min(W - 20, s.player.x));
    s.player.y = Math.max(20, Math.min(H - 20, s.player.y));
    if (s.player.invincible > 0) s.player.invincible -= dt;

    const optPos = [];
    for (let i = 0; i < s.player.optionCount; i++) {
      const sign = i % 2 === 0 ? -1 : 1;
      const dist = Math.ceil((i + 1) / 2) * 36;
      optPos.push({ x: s.player.x, y: s.player.y + sign * dist });
    }
    s.player.options = optPos;

    s.shootTimer -= dt; s.missileCooldown -= dt;
    if ((keys[" "] || keys["z"]) && s.shootTimer <= 0) {
      s.shootTimer = s.hasLaser ? 0.06 : 0.18;
      const srcs = [{ x: s.player.x + 22, y: s.player.y }, ...s.player.options.map(o => ({ x: o.x + 22, y: o.y }))];
      for (const src of srcs) {
        if (s.hasLaser) {
          s.bullets.push({ x: src.x, y: src.y, vx: 920, vy: 0, type: "laser", w: 28, h: 4 });
          if (s.hasDouble) s.bullets.push({ x: src.x, y: src.y - 10, vx: 870, vy: -72, type: "laser", w: 22, h: 3 });
        } else {
          s.bullets.push({ x: src.x, y: src.y, vx: 600, vy: 0, type: "normal", w: 14, h: 5 });
          if (s.hasDouble) s.bullets.push({ x: src.x, y: src.y - 9, vx: 550, vy: -88, type: "normal", w: 12, h: 4 });
        }
      }
      if (s.hasMissile && s.missileCooldown <= 0) {
        s.missileCooldown = 0.45;
        s.bullets.push({ x: s.player.x, y: s.player.y + 15, vx: 300, vy: 130, type: "missile", w: 10, h: 5 });
      }
    }

    if (keys["Enter"] || keys["x"]) {
      keys["Enter"] = false; keys["x"] = false;
      if (s.powerBar.length > 0) {
        const pw = s.powerBar.shift();
        if (pw === "SPEED" && s.player.speed < 5) s.player.speed++;
        if (pw === "MISSILE") s.hasMissile = true;
        if (pw === "DOUBLE") s.hasDouble = true;
        if (pw === "LASER") s.hasLaser = true;
        if (pw === "OPTION" && s.player.optionCount < 4) s.player.optionCount++;
        if (pw === "SHIELD") s.hasShield = true;
      }
    }

    s.bullets = s.bullets.filter(b => { b.x += b.vx * dt; b.y += b.vy * dt; return b.x < W + 20 && b.y > -20 && b.y < H + 20; });
    s.enemyBullets = s.enemyBullets.filter(b => { b.x += b.vx * dt; b.y += b.vy * dt; return b.x > -20 && b.x < W + 20 && b.y > -20 && b.y < H + 20; });

    s.spawnTimer -= dt;
    if (s.spawnTimer <= 0) {
      s.spawnTimer = Math.max(1.0, 2.0 - s.wave * 0.05);
      const r = Math.random();
      if (r < 0.10) {
        s.enemies.push(mkEnemy(W + 30, H / 2, "mid"));
      } else if (r < 0.60) {
        const ys = [60, 120, 200, 300, 380, 430];
        const count = 1 + Math.floor(Math.random() * 2);
        for (let i = 0; i < count; i++) s.enemies.push(mkEnemy(W + 20 + i * 40, ys[Math.floor(Math.random() * ys.length)], "small"));
      }
    }

    s.bossTimer -= dt;
    if (s.bossTimer <= 0 && !s.bossSpawned) {
      s.bossSpawned = true;
      s.bossCount++;
      if (s.bossCount >= 4) {
        const finalBoss = mkEnemy(W + 70, H / 2, "boss");
        finalBoss.imgIdx = 3;
        finalBoss.hp = 400;
        finalBoss.isFinal = true;
        s.enemies.push(finalBoss);
        const boss1 = mkEnemy(W + 70, H / 3, "boss"); boss1.imgIdx = 0; s.enemies.push(boss1);
        const boss2 = mkEnemy(W + 70, (H * 2) / 3, "boss"); boss2.imgIdx = 1; s.enemies.push(boss2);
      } else {
        const boss = mkEnemy(W + 70, H / 2, "boss");
        boss.imgIdx = Math.min(s.bossCount - 1, 3);
        s.enemies.push(boss);
      }
    }

    for (const e of s.enemies) {
      e.phase += dt * 1.5;
      if (e.type === "small") { e.x += e.vx * 60 * dt; e.y += Math.sin(e.phase) * 80 * dt; }
      else if (e.type === "mid") { e.x += e.vx * 60 * dt; e.y += Math.sin(e.phase) * 55 * dt; }
      else if (e.type === "boss") {
        e.x = Math.max(W - 170, e.x + e.vx * 60 * dt);
        e.y = H / 2 + Math.sin(e.phase * 0.5) * 145;
        e.shootTimer -= dt;
        if (e.shootTimer <= 0) {
          e.shootTimer = 1.2;
          const dx = s.player.x - e.x, dy = s.player.y - e.y, d = Math.sqrt(dx*dx+dy*dy)||1;
          s.enemyBullets.push({ x: e.x-35, y: e.y, vx: dx/d*210, vy: dy/d*210 });
        }
      }
      if (e.type !== "boss") {
        e.shootTimer -= dt;
        if (e.shootTimer <= 0) {
          e.shootTimer = e.type === "mid" ? 2.5 : 5 + Math.random() * 3;
          const dx = s.player.x - e.x, dy = s.player.y - e.y, d = Math.sqrt(dx*dx+dy*dy)||1;
          s.enemyBullets.push({ x: e.x, y: e.y, vx: dx/d*155, vy: dy/d*155 });
        }
      }
    }
    s.enemies = s.enemies.filter(e => e.x > -100 && e.hp > 0);

    const deadBullets = new Set();
    for (let i = 0; i < s.bullets.length; i++) {
      const b = s.bullets[i];
      for (const e of s.enemies) {
        const ew = e.type==="boss"?65:e.type==="mid"?28:18, eh = e.type==="boss"?65:e.type==="mid"?26:16;
        if (Math.abs(b.x-e.x)<ew/2+b.w/2 && Math.abs(b.y-e.y)<eh/2+b.h/2) {
          e.hp--; deadBullets.add(i);
          if (e.hp <= 0) {
            s.score += e.type==="boss"?5000:e.type==="mid"?500:100;
            s.wave = Math.floor(s.score / 2000);
            const cnt = e.type==="boss"?28:8;
            for (let p=0;p<cnt;p++) s.particles.push({ x:e.x, y:e.y, vx:(Math.random()-.5)*280, vy:(Math.random()-.5)*280, life:0.7, color:e.type==="boss"?"#f80":"#fa0" });
            if (Math.random()<(e.type==="mid"?.85:.4)) s.capsules.push({ x:e.x, y:e.y, type:POWER_TYPES[Math.floor(Math.random()*POWER_TYPES.length)], vx:-55, vy:0 });
            if (e.type==="boss") {
              if (e.isFinal) {
                s.finalBossKilled = true;
                for (let p = 0; p < 60; p++) s.particles.push({ x: e.x, y: e.y, vx: (Math.random()-.5)*500, vy: (Math.random()-.5)*500, life: 3.5, color:["#f80","#ff0","#f0f","#fff","#0ff"][Math.floor(Math.random()*5)] });
              }
            }
          }
        }
      }
    }
    s.bullets = s.bullets.filter((_,i)=>!deadBullets.has(i));

    s.enemies = s.enemies.filter(e => e.x > -100 && e.hp > 0);
    if (s.bossSpawned && !s.enemies.some(e => e.type === "boss")) {
      s.bossSpawned = false;
      s.bossTimer = 6;
      if (s.finalBossKilled && !s.finalBossDefeated) {
        s.finalBossDefeated = true;
        s.clearTimer = 3.5;
        setFinalScore(s.score);
      }
    }

    s.capsules = s.capsules.filter(c => {
      c.x += c.vx * dt;
      if (Math.abs(c.x-s.player.x)<28 && Math.abs(c.y-s.player.y)<28) { if(s.powerBar.length<6) s.powerBar.push(c.type); return false; }
      return c.x > -20;
    });

    if (s.player.invincible <= 0) {
      if (s.hasShield) {
        const hit = [...s.enemyBullets,...s.enemies].some(b=>Math.abs(b.x-s.player.x)<22&&Math.abs(b.y-s.player.y)<22);
        if (hit) { s.hasShield=false; s.player.invincible=1; }
      } else {
        const hit = s.enemyBullets.some(b=>Math.abs(b.x-s.player.x)<13&&Math.abs(b.y-s.player.y)<10)
          || s.enemies.some(e=>Math.abs(e.x-s.player.x)<(e.type==="boss"?60:18)&&Math.abs(e.y-s.player.y)<18);
        if (hit) {
          s.lives--; s.player.invincible=2.5;
          s.hasShield=false; s.hasLaser=false; s.hasDouble=false; s.hasMissile=false;
          s.player.optionCount=0; s.player.speed=Math.max(1,s.player.speed-2);
          for (let p=0;p<18;p++) s.particles.push({ x:s.player.x, y:s.player.y, vx:(Math.random()-.5)*240, vy:(Math.random()-.5)*240, life:0.9, color:"#08f" });
          if (s.lives<=0) { setFinalScore(s.score); audioRef.current?.pause(); setScreen("gameover"); return; }
        }
      }
    }

    for (const p of s.particles) { p.x+=p.vx*dt; p.y+=p.vy*dt; p.life-=dt; p.vx*=0.97; p.vy*=0.97; }
    s.particles = s.particles.filter(p=>p.life>0);

    // Final boss death sequence
    if (s.finalBossDefeated) {
      s.clearTimer -= dt;
      // Keep spawning explosion particles
      if (Math.random() < 0.4) {
        const cx = W * 0.6 + (Math.random()-0.5)*200;
        const cy = H * 0.5 + (Math.random()-0.5)*200;
        for(let p=0;p<6;p++) s.particles.push({x:cx,y:cy,vx:(Math.random()-.5)*300,vy:(Math.random()-.5)*300,life:1.2,color:["#f80","#ff0","#f44","#fff"][Math.floor(Math.random()*4)]});
      }
      if (s.clearTimer <= 0) { audioRef.current?.pause(); setScreen("gameclear"); return; }
    }

    // ===== DRAW =====
    ctx.fillStyle="#000010"; ctx.fillRect(0,0,W,H);
    for (const st of s.stars) { ctx.fillStyle=`rgba(255,255,255,${st.s/3})`; ctx.fillRect(st.x,st.y,st.s,st.s); }

    for (const c of s.capsules) {
      ctx.save();
      ctx.strokeStyle=POWER_COLORS[c.type]; ctx.fillStyle="rgba(0,0,20,0.6)"; ctx.lineWidth=2;
      ctx.beginPath(); ctx.arc(c.x,c.y,14,0,Math.PI*2); ctx.fill(); ctx.stroke();
      ctx.fillStyle=POWER_COLORS[c.type]; ctx.font="bold 8px monospace"; ctx.textAlign="center"; ctx.textBaseline="middle";
      ctx.fillText(c.type.slice(0,3),c.x,c.y); ctx.restore();
    }

    for (const e of s.enemies) {
      ctx.save();
      if (e.type==="boss") {
        const img = bossImgsRef.current[e.imgIdx ?? 0];
        const bw = 110, bh = 110;
        if (img && img.complete) {
          ctx.save();
          ctx.beginPath();
          ctx.arc(e.x, e.y, bw/2, 0, Math.PI*2);
          ctx.clip();
          ctx.drawImage(img, e.x - bw/2, e.y - bh/2, bw, bh);
          ctx.restore();
          // Red tint border
          ctx.strokeStyle="#f44"; ctx.lineWidth=3;
          ctx.beginPath(); ctx.arc(e.x, e.y, bw/2, 0, Math.PI*2); ctx.stroke();
        } else {
          ctx.fillStyle="#d03030";
          ctx.beginPath(); ctx.arc(e.x, e.y, 52, 0, Math.PI*2); ctx.fill();
          ctx.strokeStyle="#f88"; ctx.lineWidth=2; ctx.stroke();
        }
        // HP bar
        const maxHp = e.isFinal ? 400 : 40; const hf=e.hp/maxHp; ctx.fillStyle="#222"; ctx.fillRect(e.x-42,e.y-68,84,9);
        ctx.fillStyle=hf>.5?"#0f0":hf>.25?"#ff0":"#f00"; ctx.fillRect(e.x-42,e.y-68,84*hf,9);
        ctx.strokeStyle="#555"; ctx.lineWidth=1; ctx.strokeRect(e.x-42,e.y-68,84,9);
        // BOSS label
        ctx.fillStyle="#ff0"; ctx.font="bold 11px monospace"; ctx.textAlign="center"; ctx.textBaseline="bottom";
        ctx.fillStyle = e.isFinal ? "#f0f" : "#ff0"; ctx.fillText(e.isFinal ? "👑 FINAL BOSS" : `BOSS ${e.imgIdx+1}`, e.x, e.y-68);
      } else if (e.type==="mid") {
        ctx.fillStyle="#c060f0";
        ctx.beginPath(); ctx.moveTo(e.x+22,e.y); ctx.lineTo(e.x,e.y-18); ctx.lineTo(e.x-22,e.y-10); ctx.lineTo(e.x-18,e.y+10); ctx.lineTo(e.x,e.y+18); ctx.closePath(); ctx.fill();
        ctx.strokeStyle="#e0a0ff"; ctx.lineWidth=1.5; ctx.stroke();
      } else {
        ctx.fillStyle="#40c0ff";
        ctx.beginPath(); ctx.moveTo(e.x+13,e.y); ctx.lineTo(e.x-4,e.y-10); ctx.lineTo(e.x-13,e.y-6); ctx.lineTo(e.x-13,e.y+6); ctx.lineTo(e.x-4,e.y+10); ctx.closePath(); ctx.fill();
        ctx.strokeStyle="#80e0ff"; ctx.lineWidth=1; ctx.stroke();
      }
      ctx.restore();
    }

    for (const b of s.enemyBullets) {
      ctx.fillStyle="#f44"; ctx.beginPath(); ctx.arc(b.x,b.y,4,0,Math.PI*2); ctx.fill();
      ctx.fillStyle="rgba(255,80,80,0.22)"; ctx.beginPath(); ctx.arc(b.x,b.y,8,0,Math.PI*2); ctx.fill();
    }

    for (const b of s.bullets) {
      if (b.type==="laser") {
        const g=ctx.createLinearGradient(b.x,b.y,b.x+b.w,b.y); g.addColorStop(0,"#f0f"); g.addColorStop(1,"rgba(255,0,255,0)");
        ctx.fillStyle=g; ctx.fillRect(b.x,b.y-b.h/2,b.w,b.h);
      } else if (b.type==="missile") {
        ctx.fillStyle="#f80"; ctx.fillRect(b.x,b.y-3,b.w,b.h);
        ctx.fillStyle="#ff0"; ctx.beginPath(); ctx.arc(b.x,b.y,4,0,Math.PI*2); ctx.fill();
      } else {
        const g=ctx.createLinearGradient(b.x,b.y,b.x+b.w,b.y); g.addColorStop(0,"#fff"); g.addColorStop(0.4,"#0ff"); g.addColorStop(1,"rgba(0,200,255,0)");
        ctx.fillStyle=g; ctx.fillRect(b.x,b.y-b.h/2,b.w,b.h);
      }
    }

    for (const op of s.player.options) {
      ctx.save(); ctx.shadowColor="#0f0"; ctx.shadowBlur=10;
      ctx.fillStyle="#0f0"; ctx.beginPath(); ctx.arc(op.x,op.y,9,0,Math.PI*2); ctx.fill();
      ctx.strokeStyle="#8f8"; ctx.lineWidth=1.5; ctx.beginPath(); ctx.arc(op.x,op.y,9,0,Math.PI*2); ctx.stroke();
      ctx.restore();
    }

    const px=s.player.x, py=s.player.y;
    if (s.player.invincible<=0 || Math.floor(s.player.invincible*10)%2===0) {
      ctx.save();
      if (s.hasShield) { ctx.strokeStyle="rgba(100,150,255,0.75)"; ctx.lineWidth=3; ctx.beginPath(); ctx.arc(px,py,30,0,Math.PI*2); ctx.stroke(); }
      ctx.shadowColor="#08f"; ctx.shadowBlur=14;
      ctx.fillStyle="#c0e8ff";
      ctx.beginPath(); ctx.moveTo(px+24,py); ctx.lineTo(px+4,py-10); ctx.lineTo(px-20,py-8); ctx.lineTo(px-24,py); ctx.lineTo(px-20,py+8); ctx.lineTo(px+4,py+10); ctx.closePath(); ctx.fill();
      ctx.fillStyle="#80d0ff";
      ctx.beginPath(); ctx.moveTo(px+20,py); ctx.lineTo(px+4,py-7); ctx.lineTo(px,py); ctx.lineTo(px+4,py+7); ctx.closePath(); ctx.fill();
      ctx.fillStyle="#a0c8e8";
      ctx.beginPath(); ctx.moveTo(px-4,py-10); ctx.lineTo(px+2,py-10); ctx.lineTo(px-8,py-22); ctx.lineTo(px-18,py-14); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(px-4,py+10); ctx.lineTo(px+2,py+10); ctx.lineTo(px-8,py+22); ctx.lineTo(px-18,py+14); ctx.closePath(); ctx.fill();
      ctx.fillStyle="#4080ff"; ctx.fillRect(px-26,py-5,8,10);
      const fl=0.65+Math.random()*0.35;
      const tg=ctx.createLinearGradient(px-26,py,px-26-22*fl,py);
      tg.addColorStop(0,"rgba(120,200,255,0.9)"); tg.addColorStop(1,"rgba(0,100,255,0)");
      ctx.fillStyle=tg; ctx.fillRect(px-26-22*fl,py-4,22*fl,8);
      ctx.restore();
    }

    for (const p of s.particles) {
      ctx.save(); ctx.globalAlpha=Math.max(0,p.life*1.4);
      ctx.fillStyle=p.color; ctx.beginPath(); ctx.arc(p.x,p.y,3,0,Math.PI*2); ctx.fill(); ctx.restore();
    }

    // Flash overlay on final boss defeat
    if (s.finalBossDefeated) {
      const flashAlpha = Math.min(0.7, s.clearTimer > 3 ? (3.5 - s.clearTimer) * 1.4 : s.clearTimer / 3 * 0.3);
      ctx.save();
      ctx.fillStyle = `rgba(255,200,0,${flashAlpha})`;
      ctx.fillRect(0, 0, W, H);
      // "DEFEATED!!" text
      const textAlpha = s.clearTimer < 3 ? Math.min(1, (3 - s.clearTimer) / 0.5) : 0;
      if (textAlpha > 0) {
        ctx.globalAlpha = textAlpha;
        ctx.font = "bold 52px monospace";
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillStyle = "#ff0";
        ctx.shadowColor = "#f80"; ctx.shadowBlur = 30;
        ctx.fillText("DEFEATED!!", W/2, H/2 - 20);
        ctx.font = "20px monospace";
        ctx.fillStyle = "#fff"; ctx.shadowBlur = 0;
        ctx.fillText("宇宙の平和が戻った...", W/2, H/2 + 40);
      }
      ctx.restore();
    }

    ctx.fillStyle="#fff"; ctx.font="bold 14px monospace"; ctx.textAlign="left"; ctx.textBaseline="top";
    ctx.fillText(`SCORE: ${s.score.toString().padStart(7,"0")}`,10,8);
    ctx.textAlign="right"; ctx.fillText(`LIVES: ${"♥".repeat(Math.max(0,s.lives))}`,W-10,8);

    const barX=10, barY=H-46;
    ctx.fillStyle="rgba(0,0,0,0.65)"; ctx.fillRect(barX-4,barY-20,380,38);
    ctx.strokeStyle="#335"; ctx.lineWidth=1; ctx.strokeRect(barX-4,barY-20,380,38);
    for (let i=0;i<POWER_TYPES.length;i++) {
      const active=i<s.powerBar.length, pw=active?s.powerBar[i]:POWER_TYPES[i];
      ctx.fillStyle=active?POWER_COLORS[pw]:"rgba(50,50,70,0.5)"; ctx.fillRect(barX+i*60,barY-14,52,24);
      ctx.strokeStyle=active?"#fff":"#444"; ctx.lineWidth=1.5; ctx.strokeRect(barX+i*60,barY-14,52,24);
      ctx.fillStyle=active?"#000":"#555"; ctx.font="bold 9px monospace"; ctx.textAlign="center"; ctx.textBaseline="middle";
      ctx.fillText(pw,barX+i*60+26,barY-2);
    }
    const st2=[];
    if(s.player.speed>1)st2.push(`SPD:${s.player.speed}`);
    if(s.hasMissile)st2.push("MSL"); if(s.hasDouble)st2.push("DBL");
    if(s.hasLaser)st2.push("LSR"); if(s.player.optionCount)st2.push(`OPT:${s.player.optionCount}`);
    if(s.hasShield)st2.push("SHD");
    ctx.fillStyle="#0ff"; ctx.font="10px monospace"; ctx.textAlign="left"; ctx.textBaseline="bottom";
    ctx.fillText(st2.join("  "),barX,H-4);
    ctx.fillStyle="#777"; ctx.textAlign="right"; ctx.fillText("ENTER: パワーアップ適用",W-10,H-4);
  }

  const pressKey = (k) => { keysRef.current[k] = true; };
  const releaseKey = (k) => { keysRef.current[k] = false; };
  const tapKey = (k) => { keysRef.current[k] = true; setTimeout(() => { keysRef.current[k] = false; }, 120); };

  if (screen === "gameclear") return (
    <GameClear score={finalScore} onRetry={() => { stateRef.current = initState(); audioRef.current?.play().catch(()=>{}); setScreen("game"); }} onTitle={() => setScreen("title")} />
  );

  if (screen === "title") return (
    <div style={{ background:"#000010", width:"100%", minHeight:H+70, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", fontFamily:"monospace", color:"#fff" }}>
      <div style={{ fontSize:52, fontWeight:"bold", letterSpacing:8, color:"#0cf", textShadow:"0 0 30px #0cf,0 0 60px #08f" }}>GRADIUS</div>
      <div style={{ fontSize:18, color:"#88f", marginTop:6, letterSpacing:4 }}>— CLONE —</div>
      <div style={{ marginTop:34, fontSize:13, color:"#aaa", lineHeight:2.2, textAlign:"center" }}>
        🎮 移動: 矢印キー / WASD<br/>🔫 ショット: スペース / Z<br/>⚡ パワーアップ適用: Enter / X
      </div>
      <button onClick={startGame} style={{ marginTop:34, padding:"18px 60px", fontSize:20, fontWeight:"bold", background:"linear-gradient(135deg,#0080ff,#00c0ff)", border:"none", borderRadius:8, color:"#fff", cursor:"pointer", letterSpacing:4, boxShadow:"0 0 20px #0cf", minWidth:"160px", minHeight:"56px" }}>START</button>
    </div>
  );

  if (screen === "gameover") return (
    <div style={{ background:"#000010", width:"100%", minHeight:H+70, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", fontFamily:"monospace", color:"#fff" }}>
      <div style={{ fontSize:48, fontWeight:"bold", color:"#f44", textShadow:"0 0 20px #f00" }}>GAME OVER</div>
      <div style={{ fontSize:26, marginTop:20, color:"#ff0" }}>SCORE: {finalScore.toString().padStart(7,"0")}</div>
      <button onClick={startGame} style={{ marginTop:40, padding:"16px 50px", fontSize:18, fontWeight:"bold", background:"linear-gradient(135deg,#0080ff,#00c0ff)", border:"none", borderRadius:8, color:"#fff", cursor:"pointer", letterSpacing:3, minWidth:"140px", minHeight:"52px" }}>RETRY</button>
      <button onClick={()=>{ audioRef.current?.pause(); setScreen("title"); }} style={{ marginTop:14, padding:"14px 40px", fontSize:16, background:"transparent", border:"2px solid #557", borderRadius:8, color:"#aaa", cursor:"pointer", minWidth:"120px", minHeight:"48px" }}>TITLE</button>
    </div>
  );

  return (
    <div style={{ userSelect:"none", display:"flex", flexDirection:"column", alignItems:"center", background:"#000", width:"100%", minHeight:"100vh", padding:"12px 0", overflow:"hidden" }}>
      <div style={{ width:"100%", maxWidth:780, padding:"0 12px", boxSizing:"border-box", display:"flex", justifyContent:"center" }}>
        <canvas ref={canvasRef} width={W} height={H} style={{ display:"block", border:"2px solid #113", aspectRatio:"16/9", maxWidth:"100%", maxHeight:"56.25vw", borderRadius:12 }} />
        <div style={{ display:"flex", flexDirection:"column", gap:12, marginTop:12, width:"100%", alignItems:"center", maxWidth:780 }}>
          <div style={{ display:"grid", gridTemplateColumns:"64px 64px 64px", gridTemplateRows:"64px 64px", gap:10, justifyContent:"center" }}>
            <div />
            <button onPointerDown={()=>pressKey("ArrowUp")} onPointerUp={()=>releaseKey("ArrowUp")} onPointerLeave={()=>releaseKey("ArrowUp")}
              style={{ width:64,height:64,fontSize:24,background:"#1a1a2e",border:"1px solid #334",borderRadius:16,color:"#fff",cursor:"pointer",userSelect:"none",touchAction:"none" }}>↑</button>
            <div />
            <button onPointerDown={()=>pressKey("ArrowLeft")} onPointerUp={()=>releaseKey("ArrowLeft")} onPointerLeave={()=>releaseKey("ArrowLeft")}
              style={{ width:64,height:64,fontSize:24,background:"#1a1a2e",border:"1px solid #334",borderRadius:16,color:"#fff",cursor:"pointer",userSelect:"none",touchAction:"none" }}>←</button>
            <button onPointerDown={()=>pressKey("ArrowDown")} onPointerUp={()=>releaseKey("ArrowDown")} onPointerLeave={()=>releaseKey("ArrowDown")}
              style={{ width:64,height:64,fontSize:24,background:"#1a1a2e",border:"1px solid #334",borderRadius:16,color:"#fff",cursor:"pointer",userSelect:"none",touchAction:"none" }}>↓</button>
            <button onPointerDown={()=>pressKey("ArrowRight")} onPointerUp={()=>releaseKey("ArrowRight")} onPointerLeave={()=>releaseKey("ArrowRight")}
              style={{ width:64,height:64,fontSize:24,background:"#1a1a2e",border:"1px solid #334",borderRadius:16,color:"#fff",cursor:"pointer",userSelect:"none",touchAction:"none" }}>→</button>
          </div>
          <div style={{ display:"flex", gap:12, width:"100%", justifyContent:"center", flexWrap:"wrap" }}>
            <button onPointerDown={()=>pressKey(" ")} onPointerUp={()=>releaseKey(" ")} onPointerLeave={()=>releaseKey(" ")}
              style={{ flex:1,minWidth:120,height:60,fontSize:16,background:"#042",border:"1px solid #0a4",borderRadius:16,color:"#0f0",cursor:"pointer",userSelect:"none",touchAction:"none",fontFamily:"monospace" }}>SHOT</button>
            <button onPointerDown={()=>tapKey("Enter")} onPointerUp={()=>{}}
              style={{ flex:1,minWidth:120,height:60,fontSize:16,background:"#204",border:"1px solid #84a",borderRadius:16,color:"#c8f",cursor:"pointer",userSelect:"none",touchAction:"none",fontFamily:"monospace" }}>POWER</button>
          </div>
        </div>
      </div>
    </div>
  );
}
